const fs = require("fs");

const SERVER_PATH = "/home/user/webhook_server.js";
const REPORT_PATH = "/home/user/webhook_test_report.json";

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function runTests() {
  let serverProcess;
  const report = {
    health_check: false,
    webhook_response: null,
  };

  try {
    serverProcess = spawn("node", [SERVER_PATH], {
      stdio: "ignore",
    });

    await wait(800);

    try {
      const healthResponse = await fetch("http://localhost:3000/health");
      report.health_check = healthResponse.ok;
    } catch (error) {
      report.health_check = false;
    }

    try {
      const payload = {
        purchaseId: "order-123",
        customerEmail: "buyer@example.com",
        productName: "Starter Pack",
        amount: 49.99,
      };

      const webhookResponse = await fetch("http://localhost:3000/webhook/purchase", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const responseBody = await webhookResponse.json().catch(async () => {
        const text = await webhookResponse.text();
        return { raw: text };
      });

      report.webhook_response = responseBody;

